import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"巽下坎上 井：","description":"京氏易傳 - 巽下坎上 井：","frontmatter":{"title":"巽下坎上 井：","description":"京氏易傳 - 巽下坎上 井："},"headers":[],"relativePath":"classics/jingshi/015.md","filePath":"classics/jingshi/015.md"}'),i={name:"classics/jingshi/015.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"巽下坎上-井",tabindex:"-1"},[l("巽下坎上 井： "),e("a",{class:"header-anchor",href:"#巽下坎上-井","aria-label":"Permalink to “巽下坎上 井：”"},"​")],-1),e("p",null,"陰陽通變，不可革者，井也。井道以澄清不竭之象，而成於井之德也。《易》雲：“井者，德之基。”（虎易注：《易、系下》曰：井，德之地也。）又云：“往來井井，見功也。改邑不改井，德不可渝也。”（虎易注：此句“見功也。”“德不可渝也。”非《易》原文。讀者可參見原文。）【井道以澄清見用，為功也。井象德不可渝變也。】與坎為飛伏。【戊戌土，庚申金。】九五處至尊，應用見本象。",-1),e("p",null,"建辛巳至丙戌，【小滿至寒露。】積算起丙戌至乙酉，週而復始。【火土入卦起算數。】",-1),e("p",null,"五星從位起歲星，【木星入卦，東方用事。】尾宿從位降戊戌。【尾宿配戊戌入卦宮。】坎下見風，險於前；內外相資，益於君。【井以德立，君正民信，德以其道也。】賢人有位，君子不孤。《傳》曰：“德不孤，必有鄰。”（虎易注：此句《傳》中未考，不知道出於何處。）【六爻各處其務，反覆陰陽變化，各得其道也。】氣候所象，定數於二十八。【爻配陰陽，分人事，吉凶其見矣。】",-1),e("p",null,"天地之數，分於人事；【近取諸身，遠取諸物。】吉凶之兆，定於陰陽。陰生陽消，陽生陰滅，二氣交互，萬物生焉。",-1),e("p",null,"震至於井，陰陽代位，至極則反，與巽為終，退復於本。故曰遊魂，為大過。【降入大過卦。】",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
